/**
 * XSS Protection: Escapes all dangerous HTML characters in user-provided strings.
 * MUST be called on every piece of user data before inserting into innerHTML.
 * @param {string} str - Raw user input.
 * @returns {string} - Safe, escaped string.
 */
const escapeHTML = (str) => {
    if (str === null || str === undefined) return "";
    return String(str).replace(/[&<>'"]/g, tag => ({
        "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;"
    }[tag]));
};

/**
 * Converts a Firebase server timestamp to a relative human-readable string.
 * @param {Object} timestamp - Firestore Timestamp object.
 * @returns {string} - e.g. "3 hours ago", "Just now".
 */
const timeAgo = (timestamp) => {
    if (!timestamp) return "Just now";
    try {
        const seconds = Math.floor((new Date() - timestamp.toDate()) / 1000);
        if (seconds < 5)         return "Just now";
        if (seconds < 60)        return seconds + " seconds ago";
        const mins = Math.floor(seconds / 60);
        if (mins < 60)           return mins + " min" + (mins > 1 ? "s" : "") + " ago";
        const hrs = Math.floor(mins / 60);
        if (hrs < 24)            return hrs + " hour" + (hrs > 1 ? "s" : "") + " ago";
        const days = Math.floor(hrs / 24);
        if (days < 30)           return days + " day" + (days > 1 ? "s" : "") + " ago";
        const months = Math.floor(days / 30);
        if (months < 12)         return months + " month" + (months > 1 ? "s" : "") + " ago";
        return Math.floor(months / 12) + " years ago";
    } catch {
        return "Just now";
    }
};

/**
 * Displays a non-blocking, auto-dismissing toast notification.
 * Falls back to console.log if the toast element cannot be created.
 * @param {string} message - Text to display.
 * @param {"info"|"success"|"error"} type - Visual style of the toast.
 */
const showToast = (message, type = "info") => {
    try {
        // Remove any existing toast to prevent stacking
        const existing = document.getElementById("ttw-toast-el");
        if (existing) existing.remove();

        const toast = document.createElement("div");
        toast.id        = "ttw-toast-el";
        toast.className = `ttw-toast ${type}`;
        toast.textContent = message;
        document.body.appendChild(toast);

        // Trigger CSS transition
        requestAnimationFrame(() => {
            requestAnimationFrame(() => toast.classList.add("show"));
        });

        setTimeout(() => {
            toast.classList.remove("show");
            setTimeout(() => toast.remove(), 400);
        }, 3200);
    } catch (err) {
        console.log("[TTW Toast]", message);
    }
};

// Expose globally so other site scripts can use it (backward compatibility)
window.showToast = showToast;

/**
 * FEATURE 9 — Applies basic Markdown formatting to escaped comment text.
 * Order matters: escape first, then apply markdown to the safe string.
 * @param {string} rawText - The raw comment message from Firestore.
 * @returns {string} - HTML string with markdown converted and XSS-safe.
 */
const applyMarkdown = (rawText) => {
    if (!CFG.markdown || !CFG.markdown.enabled) {
        return escapeHTML(rawText).replace(/\n/g, "<br>");
    }
    let safe = escapeHTML(rawText);
    // Inline code: `code` → <code>code</code>
    safe = safe.replace(/`([^`]+)`/g, "<code>$1</code>");
    // Bold: **text** → <strong>text</strong>
    safe = safe.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    // Italic: *text* → <em>text</em>
    safe = safe.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    // Newlines
    safe = safe.replace(/\n/g, "<br>");
    return safe;
};

/**
 * FEATURE 11 — Replaces profanity words with asterisks before rendering.
 * Case-insensitive, whole-word matching.
 * @param {string} text - Comment text (after markdown processing).
 * @returns {string} - Cleaned text.
 */
const applyProfanityFilter = (text) => {
    if (!CFG.profanityFilter || !CFG.profanityFilter.enabled) return text;
    const words = CFG.profanityFilter.wordList || [];
    words.forEach(word => {
        const regex = new RegExp(`\\b${escapeRegExp(word)}\\b`, "gi");
        text = text.replace(regex, "*".repeat(word.length));
    });
    return text;
};

/** Escapes special characters for use inside a RegExp. */
const escapeRegExp = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * FEATURE 13 — Wraps @mentions in a styled span.
 * Applied after markdown and profanity filter.
 * @param {string} text - Processed comment HTML.
 * @returns {string} - HTML with @mention spans inserted.
 */
const applyMentions = (text) => {
    if (!CFG.mentions || !CFG.mentions.enabled) return text;
    // Match @word (not inside HTML tags) — simple, robust approach
    return text.replace(/(?<![a-zA-Z0-9])@([a-zA-Z0-9_]+)/g,
        '<span class="ttw-mention">@$1</span>');
};

/**
 * Runs the full text processing pipeline on a raw comment message.
 * Pipeline: Markdown → Profanity Filter → @Mentions
 * @param {string} rawText - Raw message string from Firestore.
 * @returns {string} - Final safe HTML to inject into innerHTML.
 */
const processCommentText = (rawText) => {
    let processed = applyMarkdown(rawText);
    processed     = applyProfanityFilter(processed);
    processed     = applyMentions(processed);
    return processed;
};

/**
 * FEATURE 8 — Checks if the current user is within the anti-spam cooldown period.
 * Uses localStorage to persist the last post timestamp across page reloads.
 * @returns {number} - Remaining seconds (0 if user can post freely).
 */
const getCooldownRemaining = () => {
    const cooldown = (CFG.antiSpam && CFG.antiSpam.cooldownSeconds) || 30;
    const lastPost = parseInt(localStorage.getItem("ttw_last_post") || "0", 10);
    const elapsed  = Math.floor(Date.now() / 1000) - lastPost;
    return elapsed >= cooldown ? 0 : cooldown - elapsed;
};

/** Records the current timestamp as the user's last post time. */
const recordPostTimestamp = () => {
    localStorage.setItem("ttw_last_post", Math.floor(Date.now() / 1000).toString());
};


