/**
 * Main entry point. Finds the widget container, resolves the page ID,
 * injects the HTML skeleton, and starts all subsystems.
 */
const initWidget = () => {
    const widgetContainer = document.querySelector(".trusted-comments-widget");
    if (!widgetContainer) {
        console.warn("[TTW Comments] Widget container '.trusted-comments-widget' not found on this page.");
        return;
    }

    // Resolve page ID from data attribute or auto-detect from URL
    const rawPageId = widgetContainer.getAttribute("data-page-id");
    if (!rawPageId || rawPageId === "auto") {
        currentPageId = window.location.pathname.split("/").pop().replace(".html", "") || "home";
    } else {
        currentPageId = rawPageId;
    }

    // Inject the full widget HTML skeleton
    widgetContainer.innerHTML = buildWidgetShell();

    // Wire up all event listeners via delegation
    setupEventListeners();

    // Start Firebase auth watcher
    listenToAuthChanges();

    // Load initial batch of comments
    fetchCommentsBatch(true);
};

