// ══════════════════════════════════════════════════════════════════════════════
// SECTION 5 — EVENT DELEGATION
// One listener on the widget root handles ALL dynamic child interactions.
// ══════════════════════════════════════════════════════════════════════════════

const setupEventListeners = () => {
    const container = document.querySelector(".trusted-comments-widget");
    if (!container) return;

    // ── Primary click handler (event delegation) ──────────────────────────────
    container.addEventListener("click", async (e) => {
        const target = e.target;

        // --- AUTH ---
        if (target.closest("#ttw-login-btn")) {
            await handleLogin();
            return;
        }
        if (target.closest("#ttw-logout-btn")) {
            await handleLogout();
            return;
        }

        // --- POST MAIN COMMENT ---
        if (target.closest("#ttw-post-btn")) {
            handlePostComment(null, "ttw-main-input", "ttw-post-btn");
            return;
        }

        // --- REPLY TOGGLE ---
        if (target.closest(".ttw-btn-reply")) {
            const btn       = target.closest(".ttw-btn-reply");
            const commentId = btn.getAttribute("data-id");
            const replyBox  = document.getElementById("reply-container-" + commentId);
            if (replyBox) {
                replyBox.classList.toggle("active");
                if (replyBox.classList.contains("active")) {
                    replyBox.querySelector("textarea").focus();
                }
            }
            return;
        }

        // --- SUBMIT REPLY ---
        if (target.closest(".ttw-submit-reply-btn")) {
            const btn      = target.closest(".ttw-submit-reply-btn");
            const parentId = btn.getAttribute("data-parent-id");
            handlePostComment(parentId, "reply-input-" + parentId, btn.id);
            return;
        }

        // --- FEATURE 3: EDIT COMMENT ---
        if (target.closest(".ttw-btn-edit")) {
            const btn       = target.closest(".ttw-btn-edit");
            const commentId = btn.getAttribute("data-id");
            toggleEditMode(commentId, true);
            return;
        }

        // --- FEATURE 3: CANCEL EDIT ---
        if (target.closest(".ttw-btn-cancel-edit")) {
            const btn       = target.closest(".ttw-btn-cancel-edit");
            const commentId = btn.getAttribute("data-id");
            toggleEditMode(commentId, false);
            return;
        }

        // --- FEATURE 3: SAVE EDIT ---
        if (target.closest(".ttw-btn-save-edit")) {
            const btn       = target.closest(".ttw-btn-save-edit");
            const commentId = btn.getAttribute("data-id");
            handleSaveEdit(commentId);
            return;
        }

        // --- DELETE COMMENT (Author or Admin) ---
        if (target.closest(".ttw-btn-delete")) {
            const btn       = target.closest(".ttw-btn-delete");
            const commentId = btn.getAttribute("data-id");
            if (confirm("Are you sure you want to delete this comment permanently?")) {
                handleDeleteComment(commentId);
            }
            return;
        }

        // --- FEATURE 5: UPVOTE ---
        if (target.closest(".ttw-btn-upvote")) {
            const btn       = target.closest(".ttw-btn-upvote");
            const commentId = btn.getAttribute("data-id");
            handleUpvote(commentId);
            return;
        }

        // --- FEATURE 6: PIN/UNPIN (Admin only) ---
        if (target.closest(".ttw-btn-pin")) {
            const btn       = target.closest(".ttw-btn-pin");
            const commentId = btn.getAttribute("data-id");
            const isPinned  = btn.getAttribute("data-pinned") === "true";
            handlePinComment(commentId, !isPinned);
            return;
        }

        // --- FEATURE 1: IMAGE LIGHTBOX ---
        if (target.closest(".ttw-comment-image")) {
            const imgSrc = target.closest(".ttw-comment-image").getAttribute("src");
            openLightbox(imgSrc);
            return;
        }

        // --- CLOSE LIGHTBOX ---
        if (target.closest(".ttw-lightbox")) {
            target.closest(".ttw-lightbox").remove();
            return;
        }

        // --- FEATURE 1: IMAGE REMOVE (pre-upload) ---
        if (target.closest("#ttw-image-remove-btn")) {
            clearPendingImage();
            return;
        }

        // --- FEATURE 14: EXPORT MY DATA ---
        if (target.closest("#ttw-export-btn")) {
            handleExportData();
            return;
        }

        // --- FEATURE 7: LOAD MORE ---
        if (target.closest("#ttw-load-more-btn")) {
            fetchCommentsBatch(false);
            return;
        }

        // --- FEATURE 2 UPGRADE: VOICE RETAKE ---
        if (target.closest("#ttw-btn-voice-retake")) {
            handleVoiceRetake();
            return;
        }

        // --- FEATURE 2 UPGRADE: CLEAN VOICE TOGGLE ---
        if (target.closest("#ttw-btn-voice-clean")) {
            handleVoiceCleanToggle();
            return;
        }

        // --- FEATURE 2 UPGRADE: PREVIEW PLAY/PAUSE ---
        if (target.closest("#ttw-preview-play-btn")) {
            togglePreviewPlayback();
            return;
        }
    });

    // ── Sort dropdown change ──────────────────────────────────────────────────
    container.addEventListener("change", (e) => {
        if (e.target.id === "ttw-sort-select") {
            currentSort = e.target.value;
            renderCommentsUI();
        }
    });

    // ── FEATURE 1: Image file input change ────────────────────────────────────
    container.addEventListener("change", (e) => {
        if (e.target.id === "ttw-image-file-input") {
            handleImageFileSelected(e.target.files[0]);
        }
    });

    // ── FEATURE 1: Trigger file picker on button click ────────────────────────
    container.addEventListener("click", (e) => {
        if (e.target.closest("#ttw-btn-image")) {
            const fileInput = document.getElementById("ttw-image-file-input");
            if (fileInput) fileInput.click();
        }
    });

    // ── FEATURE 2: Voice record button ───────────────────────────────────────
    container.addEventListener("click", (e) => {
        if (e.target.closest("#ttw-btn-record")) {
            if (mediaRecorder && mediaRecorder.state === "recording") {
                stopRecording();
            } else {
                startRecording();
            }
        }
    });

    // ── FEATURE 2: Custom audio player controls (delegated) ──────────────────
    container.addEventListener("click", (e) => {
        const playBtn = e.target.closest(".ttw-audio-play-btn");
        if (playBtn) {
            const player = playBtn.closest(".ttw-audio-player");
            if (player) toggleAudioPlayer(player);
        }
    });

    // Allow clicking the progress bar to seek (existing comment players)
    container.addEventListener("click", (e) => {
        const progressWrap = e.target.closest(".ttw-audio-progress-wrap");
        if (progressWrap) {
            const player  = progressWrap.closest(".ttw-audio-player");
            const audioEl = player && player.querySelector("audio");
            if (audioEl && audioEl.duration) {
                const rect   = progressWrap.getBoundingClientRect();
                const ratio  = (e.clientX - rect.left) / rect.width;
                audioEl.currentTime = ratio * audioEl.duration;
            }
        }
    });

    // ── FEATURE 2 UPGRADE: Seek inside the preview player progress bar ────────
    container.addEventListener("click", (e) => {
        const previewWrap = e.target.closest("#ttw-preview-progress-wrap");
        if (previewWrap && previewAudioEl && previewAudioEl.duration) {
            const rect  = previewWrap.getBoundingClientRect();
            const ratio = (e.clientX - rect.left) / rect.width;
            previewAudioEl.currentTime = ratio * previewAudioEl.duration;
        }
    });
};


