// ══════════════════════════════════════════════════════════════════════════════
// SECTION 7 — DATA FETCHING (FEATURE 7: PAGINATION)
// Uses Firestore query cursors for efficient "Load More" pagination.
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Fetches a batch of top-level comments from Firestore.
 * On first call (reset=true), clears existing data and resets the cursor.
 * On subsequent calls, appends to existing data using the stored cursor.
 * @param {boolean} reset - If true, starts from the beginning.
 */
const fetchCommentsBatch = async (reset = false) => {
    if (!db || !commentsRef) return;

    const pageSize = (CFG.pagination && CFG.pagination.commentsPerPage) || 10;

    if (reset) {
        commentsData     = [];
        lastVisibleDoc   = null;
        allCommentsLoaded= false;
        // Unsubscribe from any existing realtime listener before re-subscribing
        if (realtimeUnsub) { realtimeUnsub(); realtimeUnsub = null; }
    }

    if (allCommentsLoaded) return;

    // Show loading state on Load More button
    const loadMoreBtn = document.getElementById("ttw-load-more-btn");
    if (loadMoreBtn) {
        loadMoreBtn.disabled = true;
        loadMoreBtn.innerHTML = '<span class="ttw-spinner"></span> Loading…';
    }

    try {
        // Build the paginated query
        // We fetch pageId-scoped, ordered by timestamp descending
        let q = query(
            commentsRef,
            where("pageId", "==", currentPageId),
            where("parentId", "==", null),  // Only top-level comments for pagination
            orderBy("timestamp", "desc"),
            limit(pageSize)
        );

        if (lastVisibleDoc) {
            q = query(
                commentsRef,
                where("pageId", "==", currentPageId),
                where("parentId", "==", null),
                orderBy("timestamp", "desc"),
                startAfter(lastVisibleDoc),
                limit(pageSize)
            );
        }

        // Use a one-time get for the paginated batch, then
        // set up a realtime listener only on the FIRST batch for live updates
        const snapshot = await getDocs(q);

        if (snapshot.empty && reset) {
            commentsData     = [];
            allCommentsLoaded= true;
            renderCommentsUI();
            updateLoadMoreVisibility(0);
            return;
        }

        const newDocs = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
        commentsData = [...commentsData, ...newDocs];
        lastVisibleDoc = snapshot.docs[snapshot.docs.length - 1];

        if (snapshot.docs.length < pageSize) {
            allCommentsLoaded = true;
        }

        // Fetch all replies for the currently loaded top-level comments in one shot
        await fetchRepliesForBatch(newDocs.map(d => d.id));

        renderCommentsUI();
        updateLoadMoreVisibility(snapshot.docs.length);

        // Set up a realtime listener on the FIRST load for live new-comment updates
        if (reset) {
            setupRealtimeListener();
        }

    } catch (err) {
        console.error("[TTW Comments] Fetch Error:", err);
        showToast("Failed to load comments. Please refresh.", "error");
    } finally {
        if (loadMoreBtn) {
            loadMoreBtn.disabled = false;
            loadMoreBtn.innerHTML = '<i class="fa-solid fa-chevron-down"></i> Load More';
        }
    }
};

/**
 * Fetches all replies (nested comments) for a given array of parent comment IDs.
 * Replies are NOT paginated — they load with their parent.
 * @param {string[]} parentIds - Array of parent comment document IDs.
 */
const fetchRepliesForBatch = async (parentIds) => {
    if (!parentIds.length) return;
    try {
        // Remove previously fetched replies for these parents to avoid duplicates on refresh
        commentsData = commentsData.filter(c => !c.parentId || !parentIds.includes(c.parentId));

        const q        = query(commentsRef, where("pageId", "==", currentPageId), where("parentId", "in", parentIds));
        const snapshot = await getDocs(q);
        const replies  = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
        commentsData   = [...commentsData, ...replies];
    } catch (err) {
        console.error("[TTW Comments] Reply Fetch Error:", err);
    }
};

/**
 * Sets up a realtime Firestore listener to catch comments posted AFTER
 * the initial page load. New comments are appended without full re-fetch.
 */
const setupRealtimeListener = () => {
    if (!db) return;

    // Listen for documents newer than now
    const now = new Date();
    const q   = query(
        commentsRef,
        where("pageId", "==", currentPageId),
        where("timestamp", ">", now),
        orderBy("timestamp", "asc")
    );

    realtimeUnsub = onSnapshot(q, (snapshot) => {
        let changed = false;
        snapshot.docChanges().forEach((change) => {
            const newDoc = { id: change.doc.id, ...change.doc.data() };
            if (change.type === "added") {
                // Avoid duplicates
                if (!commentsData.find(c => c.id === newDoc.id)) {
                    commentsData.unshift(newDoc); // Prepend to show at top
                    changed = true;
                }
            }
            if (change.type === "modified") {
                const idx = commentsData.findIndex(c => c.id === newDoc.id);
                if (idx !== -1) { commentsData[idx] = newDoc; changed = true; }
            }
            if (change.type === "removed") {
                commentsData = commentsData.filter(c => c.id !== newDoc.id);
                changed = true;
            }
        });
        if (changed) renderCommentsUI();
    }, (err) => {
        console.error("[TTW Comments] Realtime Listener Error:", err);
    });
};

/** Shows or hides the Load More button based on pagination state. */
const updateLoadMoreVisibility = (fetchedCount) => {
    const wrap = document.getElementById("ttw-load-more-wrap");
    if (!wrap) return;
    wrap.style.display = allCommentsLoaded ? "none" : "block";
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 8 — POST, EDIT, DELETE, UPVOTE, PIN
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Core function for posting both main comments and nested replies.
 * Handles validation, anti-spam, GDPR check, image upload, audio upload,
 * Firestore write, and Telegram notification.
 *
 * @param {string|null} parentId      - null for top-level, doc ID for replies.
 * @param {string}      inputElementId - DOM ID of the textarea.
 * @param {string}      buttonId       - DOM ID of the submit button.
 */
const handlePostComment = async (parentId, inputElementId, buttonId) => {
    if (!currentUser) { showToast("Please sign in to comment.", "error"); return; }

    const inputEl = document.getElementById(inputElementId);
    const btnEl   = document.getElementById(buttonId);
    if (!inputEl)   return;

    const message = inputEl.value.trim();

    // Require at least text OR an image OR audio
    if (!message && !pendingImageFile && !pendingAudioBlob) {
        showToast("Comment cannot be empty.", "error");
        return;
    }

    // FEATURE 14 — GDPR consent check (only on main comment box, not replies)
    if (!parentId && CFG.gdpr && CFG.gdpr.consentCheckboxEnabled) {
        const gdprCheckbox = document.getElementById("ttw-gdpr-checkbox");
        if (gdprCheckbox && !gdprCheckbox.checked) {
            showToast("Please accept the data storage agreement to post.", "error");
            return;
        }
    }

    // FEATURE 8 — Anti-spam cooldown check
    const remaining = getCooldownRemaining();
    if (remaining > 0) {
        showToast(`Please wait ${remaining}s before posting again.`, "error");
        startCooldownDisplayTimer();
        return;
    }

    // Disable UI to prevent double-submission
    if (inputEl) inputEl.disabled = true;
    if (btnEl)   { btnEl.disabled = true; btnEl.innerHTML = '<span class="ttw-spinner"></span> Posting…'; }

    let imageURL = null;
    let audioURL = null;

    try {
        // FEATURE 1 — Upload pending image to ImgBB
        if (pendingImageFile) {
            showUploadProgress(true);
            imageURL = await uploadImageToImgBB(pendingImageFile);
            showUploadProgress(false);
            if (!imageURL) { showToast("Image upload failed. Try again.", "error"); return; }
        }

        // FEATURE 2 — Upload pending audio to Cloudinary
        // pendingAudioBlob is always the correct blob to upload:
        // either the raw blob (clean voice off) or the processed blob (clean voice on).
        if (pendingAudioBlob) {
            showUploadProgress(true);
            audioURL = await uploadAudioToCloudinary(pendingAudioBlob);
            showUploadProgress(false);
            if (!audioURL) { showToast("Audio upload failed. Try again.", "error"); return; }
        }

        // Build the Firestore document payload
        const docData = {
            pageId     : currentPageId,
            uid        : currentUser.uid,
            name       : currentUser.displayName || "Anonymous",
            photoURL   : currentUser.photoURL    || "",
            email      : currentUser.email       || "",
            message    : message,
            timestamp  : serverTimestamp(),
            isAdmin    : ADMIN_EMAILS.includes(currentUser.email),
            parentId   : parentId || null,
            upvotes    : 0,
            upvotedBy  : [],
            isPinned   : false,
            isEdited   : false
        };

        // Attach optional media fields only if present
        if (imageURL) docData.imageURL = imageURL;
        if (audioURL) docData.audioURL = audioURL;

        await addDoc(commentsRef, docData);

        // Record post time for anti-spam cooldown
        recordPostTimestamp();
        startCooldownDisplayTimer();

        // Clear input and staged attachments
        inputEl.value = "";
        clearPendingImage();
        clearPendingAudio();

        if (parentId) {
            const replyBox = document.getElementById("reply-container-" + parentId);
            if (replyBox) replyBox.classList.remove("active");
        }

        showToast("Comment posted! ✓", "success");

        // FEATURE 4 — Telegram notification (fire-and-forget, non-blocking)
        sendTelegramNotification(message, currentUser.displayName);

    } catch (err) {
        console.error("[TTW Comments] Post Error:", err);
        showToast("Failed to post comment. Please try again.", "error");
    } finally {
        if (inputEl) inputEl.disabled = false;
        if (btnEl)   { btnEl.disabled = false; btnEl.innerHTML = 'Post Comment <i class="fa-solid fa-paper-plane"></i>'; }
    }
};

/**
 * FEATURE 3 — Saves an edited comment message back to Firestore.
 * Only updates the 'message', 'isEdited', and 'editedAt' fields (enforced by rules).
 * @param {string} commentId - The Firestore document ID of the comment to edit.
 */
const handleSaveEdit = async (commentId) => {
    const editTextarea = document.getElementById("edit-textarea-" + commentId);
    if (!editTextarea) return;

    const newMessage = editTextarea.value.trim();
    if (!newMessage) { showToast("Edited comment cannot be empty.", "error"); return; }

    const saveBtn = document.querySelector(`.ttw-btn-save-edit[data-id="${commentId}"]`);
    if (saveBtn) { saveBtn.disabled = true; saveBtn.innerHTML = '<span class="ttw-spinner"></span>'; }

    try {
        await updateDoc(doc(db, "website_comments", commentId), {
            message  : newMessage,
            isEdited : true,
            editedAt : serverTimestamp()
        });

        // Update local cache without full re-fetch
        const local = commentsData.find(c => c.id === commentId);
        if (local)  { local.message = newMessage; local.isEdited = true; }

        toggleEditMode(commentId, false);
        renderCommentsUI();
        showToast("Comment updated.", "success");
    } catch (err) {
        console.error("[TTW Comments] Edit Error:", err);
        showToast("Failed to save edit. Check permissions.", "error");
    } finally {
        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerHTML = 'Save'; }
    }
};

/**
 * Deletes a comment document from Firestore.
 * Firestore rules enforce that only the author or admin can do this.
 * @param {string} docId - The Firestore document ID to delete.
 */
const handleDeleteComment = async (docId) => {
    try {
        await deleteDoc(doc(db, "website_comments", docId));
        commentsData = commentsData.filter(c => c.id !== docId && c.parentId !== docId);
        renderCommentsUI();
        showToast("Comment deleted.", "info");
    } catch (err) {
        console.error("[TTW Comments] Delete Error:", err);
        showToast("Failed to delete. Check permissions.", "error");
    }
};

/**
 * FEATURE 5 — Toggles an upvote for the current user on a comment.
 * Uses Firestore arrayUnion/arrayRemove to safely track voters.
 * Firestore rules restrict upvote updates to only the upvotes/upvotedBy fields.
 * @param {string} commentId - The Firestore document ID.
 */
const handleUpvote = async (commentId) => {
    if (!currentUser) { showToast("Sign in to like comments.", "error"); return; }

    const commentDoc = commentsData.find(c => c.id === commentId);
    if (!commentDoc) return;

    const uid         = currentUser.uid;
    const hasVoted    = (commentDoc.upvotedBy || []).includes(uid);
    const docRef      = doc(db, "website_comments", commentId);

    // Optimistic local update for instant UI feedback
    const btn       = document.querySelector(`.ttw-btn-upvote[data-id="${commentId}"]`);
    const countEl   = btn && btn.querySelector(".ttw-upvote-count");
    const newCount  = (commentDoc.upvotes || 0) + (hasVoted ? -1 : 1);
    if (countEl) countEl.textContent = newCount;
    if (btn)     btn.classList.toggle("voted", !hasVoted);

    // Persist local state immediately
    commentDoc.upvotes    = newCount;
    commentDoc.upvotedBy  = hasVoted
        ? (commentDoc.upvotedBy || []).filter(u => u !== uid)
        : [...(commentDoc.upvotedBy || []), uid];

    try {
        await updateDoc(docRef, {
            upvotes   : increment(hasVoted ? -1 : 1),
            upvotedBy : hasVoted ? arrayRemove(uid) : arrayUnion(uid)
        });
    } catch (err) {
        console.error("[TTW Comments] Upvote Error:", err);
        // Revert optimistic update on failure
        commentDoc.upvotes    = (commentDoc.upvotes || 0) + (hasVoted ? 1 : -1);
        commentDoc.upvotedBy  = hasVoted
            ? [...(commentDoc.upvotedBy || []), uid]
            : (commentDoc.upvotedBy || []).filter(u => u !== uid);
        renderCommentsUI();
        showToast("Failed to update vote.", "error");
    }
};

/**
 * FEATURE 6 — Pins or unpins a comment. Admin only.
 * @param {string}  commentId - Firestore document ID.
 * @param {boolean} pin       - true to pin, false to unpin.
 */
const handlePinComment = async (commentId, pin) => {
    if (!currentUser || !ADMIN_EMAILS.includes(currentUser.email)) {
        showToast("Admin access required.", "error");
        return;
    }
    try {
        await updateDoc(doc(db, "website_comments", commentId), { isPinned: pin });
        const local = commentsData.find(c => c.id === commentId);
        if (local) local.isPinned = pin;
        renderCommentsUI();
        showToast(pin ? "Comment pinned to top. 📌" : "Comment unpinned.", "info");
    } catch (err) {
        console.error("[TTW Comments] Pin Error:", err);
        showToast("Failed to pin comment.", "error");
    }
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 9 — FEATURE 1: IMAGE ATTACHMENT
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Validates and stages a selected image file for upload on post.
 * Shows a thumbnail preview in the input area.
 * Includes strict file type and size validation.
 * @param {File} file - The File object from the file input.
 */
const handleImageFileSelected = (file) => {
    if (!file) return;

    // 1. Validate File Type (Security Check: Ensure it's actually an image)
    if (!file.type.startsWith("image/")) {
        showToast("Invalid file type. Please select an image file.", "error");
        return;
    }

    // 2. Validate File Size (Ensure it doesn't exceed the configured limit)
    const maxMB = (CFG.imageAttachments && CFG.imageAttachments.maxSizeMB) || 5;
    if (file.size > maxMB * 1024 * 1024) {
        showToast(`Image must be under ${maxMB}MB.`, "error");
        return;
    }

    // 3. Stage the file and generate a base64 preview for the UI
    pendingImageFile = file;
    const reader = new FileReader();
    reader.onload = (e) => {
        pendingImageDataURL = e.target.result;
        renderImagePreview(pendingImageDataURL);
    };
    reader.readAsDataURL(file);
};

/** Renders the image thumbnail preview in the input toolbar area. */
const renderImagePreview = (dataURL) => {
    const previewArea = document.getElementById("ttw-image-preview-area");
    if (!previewArea) return;
    previewArea.innerHTML = `
        <div class="ttw-image-preview-wrap">
            <img src="${dataURL}" alt="Attachment preview">
            <button class="ttw-image-remove-btn" id="ttw-image-remove-btn" title="Remove image">✕</button>
        </div>
    `;
};

/** Clears the staged image file and removes its preview from the DOM. */
const clearPendingImage = () => {
    pendingImageFile    = null;
    pendingImageDataURL = null;
    const previewArea = document.getElementById("ttw-image-preview-area");
    if (previewArea) previewArea.innerHTML = "";
    const fileInput = document.getElementById("ttw-image-file-input");
    if (fileInput)  fileInput.value = "";
};

// Define your Cloudflare Worker URL
const WORKER_URL = "https://ttw-upload-api.kawsar98dd.workers.dev";

/**
 * ============================================================================
 * UPLOAD HANDLERS: IMGBB & CLOUDINARY
 * ============================================================================
 * These functions securely communicate with the Cloudflare Worker proxy
 * to upload media without exposing API keys on the client side.
 */

/**
 * Uploads an image File to ImgBB via Cloudflare Worker Proxy.
 * @param {File} file - The image file to upload.
 * @returns {Promise<string|null>} - The direct image URL, or null on failure.
 */
const uploadImageToImgBB = async (file) => {
    const formData = new FormData();
    formData.append("image", file);

    try {
        const resp = await fetch(`${WORKER_URL}/upload-image`, {
            method: "POST",
            body: formData
        });

        const json = await resp.json();

        // Check for HTTP errors or ImgBB specific success flag
        if (!resp.ok || !json.success) {
            console.error("[TTW Comments] ImgBB Upload Error via Worker:", json);
            showToast("Image upload failed. Please try again.", "error");
            return null;
        }

        return json.data.url;
    } catch (err) {
        console.error("[TTW Comments] Fetch Error (ImgBB Worker):", err);
        showToast("Network error during image upload.", "error");
        return null;
    }
};

/**
 * Opens a full-screen lightbox for viewing comment images.
 * Clicking anywhere on the overlay closes it.
 * @param {string} src - Image URL.
 */
const openLightbox = (src) => {
    const existing = document.querySelector(".ttw-lightbox");
    if (existing) existing.remove();

    const overlay = document.createElement("div");
    overlay.className = "ttw-lightbox";
    overlay.innerHTML = `<img src="${escapeHTML(src)}" alt="Full size image">`;
    document.body.appendChild(overlay);
};

/** Shows or hides the upload progress animation. */
const showUploadProgress = (show) => {
    const wrap = document.getElementById("ttw-upload-progress");
    if (wrap) wrap.classList.toggle("active", show);
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 10 — FEATURE 2: VOICE NOTES (MediaRecorder + Cloudinary)
//              UPGRADED v2.1: Audio Preview UI + Web Audio Clean/Enhance
// ══════════════════════════════════════════════════════════════════════════════

/** Requests microphone permission and starts audio recording. */
const startRecording = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        showToast("Voice recording is not supported in this browser.", "error");
        return;
    }

    try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        recordingChunks = [];
        mediaRecorder   = new MediaRecorder(stream);

        mediaRecorder.ondataavailable = (e) => {
            if (e.data && e.data.size > 0) recordingChunks.push(e.data);
        };

        mediaRecorder.onstop = () => {
            // Combine recorded chunks into a single Blob
            const blob = new Blob(recordingChunks, { type: "audio/webm" });
            stream.getTracks().forEach(track => track.stop()); // Release mic
            clearRecordingTimer();
            updateRecordBtnUI(false);

            // ── FEATURE 2 UPGRADE: branch on enableVoiceEnhance ──────────────
            const useEnhance = !!(CFG.voiceNotes && CFG.voiceNotes.enableVoiceEnhance);

            if (useEnhance) {
                // Store the raw blob and show the preview panel; do NOT stage yet.
                rawAudioBlob     = blob;
                pendingAudioBlob = blob; // default — overwritten if user cleans
                voiceCleanEnabled = false;
                showVoicePreviewPanel(blob);
            } else {
                // Legacy behaviour: stage immediately, no preview UI.
                pendingAudioBlob = blob;
                showToast("Recording saved. Click 'Post Comment' to upload.", "success");
            }
        };

        mediaRecorder.start(250); // Collect data every 250ms
        updateRecordBtnUI(true);
        startRecordingTimer();

        // FEATURE 2 — Auto-stop at configured max duration
        const maxSecs = (CFG.voiceNotes && CFG.voiceNotes.maxDurationSeconds) || 60;
        setTimeout(() => {
            if (mediaRecorder && mediaRecorder.state === "recording") {
                showToast(`Max recording length (${maxSecs}s) reached.`, "info");
                stopRecording();
            }
        }, maxSecs * 1000);

    } catch (err) {
        console.error("[TTW] Microphone Error:", err);
        showToast("Microphone access denied.", "error");
    }
};

/** Stops the active MediaRecorder. The onstop handler builds the Blob. */
const stopRecording = () => {
    if (mediaRecorder && mediaRecorder.state === "recording") {
        mediaRecorder.stop();
    }
};

/** Starts the visible recording duration counter. */
const startRecordingTimer = () => {
    recordingSeconds = 0;
    const timerEl   = document.getElementById("ttw-record-seconds");
    const timerWrap = document.getElementById("ttw-record-timer");
    if (timerWrap) timerWrap.classList.add("active");

    recordingTimer = setInterval(() => {
        recordingSeconds++;
        const mins = Math.floor(recordingSeconds / 60);
        const secs = recordingSeconds % 60;
        if (timerEl) timerEl.textContent = `${mins}:${secs.toString().padStart(2, "0")}`;
    }, 1000);
};

/** Clears the recording timer interval and hides the timer display. */
const clearRecordingTimer = () => {
    if (recordingTimer) { clearInterval(recordingTimer); recordingTimer = null; }
    const timerWrap = document.getElementById("ttw-record-timer");
    if (timerWrap)  timerWrap.classList.remove("active");
    recordingSeconds = 0;
};

/**
 * Updates the record button icon and class to reflect recording state.
 * @param {boolean} isRecording - True if currently recording.
 */
const updateRecordBtnUI = (isRecording) => {
    const btn = document.getElementById("ttw-btn-record");
    if (!btn) return;
    btn.classList.toggle("recording", isRecording);
    btn.innerHTML = isRecording
        ? '<i class="fa-solid fa-stop"></i> Stop'
        : '<i class="fa-solid fa-microphone"></i> Voice';
};

/**
 * Clears any staged audio blob and resets all voice note state.
 * Called on logout, retake, and after a successful post.
 */
const clearPendingAudio = () => {
    // Stop and destroy the preview audio element if it exists
    if (previewAudioEl) {
        previewAudioEl.pause();
        previewAudioEl.src = "";
    }
    previewAudioEl    = null;
    pendingAudioBlob  = null;
    rawAudioBlob      = null;
    voiceCleanEnabled = false;
    recordingChunks   = [];
    clearRecordingTimer();
    updateRecordBtnUI(false);
    hideVoicePreviewPanel();
};

/**
 * Uploads an audio Blob to Cloudinary via Cloudflare Worker Proxy.
 * @param {Blob} audioBlob - The audio data from MediaRecorder (raw or processed).
 * @returns {Promise<string|null>} - The Cloudinary URL, or null on failure.
 */
const uploadAudioToCloudinary = async (audioBlob) => {
    // Ensure this preset is configured as "Unsigned" in your Cloudinary dashboard
    const preset = (CFG.voiceNotes && CFG.voiceNotes.uploadPreset) || "ttw_audio_preset";

    const formData = new FormData();
    formData.append("file", audioBlob);
    formData.append("upload_preset", preset);

    try {
        const resp = await fetch(`${WORKER_URL}/upload-audio`, {
            method: "POST",
            body: formData
        });

        const json = await resp.json();

        // Check for HTTP errors from Worker or explicit errors from Cloudinary
        if (!resp.ok || json.error) {
            console.error("[TTW Comments] Cloudinary Upload Error via Worker:", json);
            showToast("Audio upload failed. Please try again.", "error");
            return null;
        }

        return json.secure_url;
    } catch (err) {
        console.error("[TTW Comments] Fetch Error (Cloudinary Worker):", err);
        showToast("Network error during audio upload.", "error");
        return null;
    }
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 10b — FEATURE 2 UPGRADE: VOICE PREVIEW & WEB AUDIO PROCESSING
// All functions in this section are ADDITIVE. Nothing above is altered.
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Shows the Voice Preview Panel after a recording finishes.
 * Loads the raw blob into the hidden <audio> element for immediate playback.
 * @param {Blob} blob - The raw audio blob from MediaRecorder.
 */
const showVoicePreviewPanel = (blob) => {
    const panel = document.getElementById("ttw-voice-preview-panel");
    if (!panel) return; // Panel not in DOM if enableVoiceEnhance is false

    // Get (or create) the preview audio element
    previewAudioEl = document.getElementById("ttw-preview-audio-el");
    if (!previewAudioEl) return;

    // Point the audio element at a fresh object URL for the blob
    if (previewAudioEl.src) {
        URL.revokeObjectURL(previewAudioEl.src); // Release any previous object URL
    }
    previewAudioEl.src = URL.createObjectURL(blob);
    previewAudioEl.load();

    // Wire up progress / time listeners (safe to re-add; they are idempotent)
    attachPreviewAudioListeners();

    // Reset UI state
    resetPreviewPlayerUI();

    // Reset Clean Voice button and status badge
    const cleanBtn    = document.getElementById("ttw-btn-voice-clean");
    const statusBadge = document.getElementById("ttw-voice-enhance-status");
    if (cleanBtn)    { cleanBtn.classList.remove("active"); }
    if (statusBadge) { statusBadge.classList.remove("active"); }

    // Show the panel with animation
    panel.classList.add("active");

    showToast("Recording ready. Preview it before posting.", "info");
};

/** Hides the Voice Preview Panel and resets its internal UI state. */
const hideVoicePreviewPanel = () => {
    const panel = document.getElementById("ttw-voice-preview-panel");
    if (panel) panel.classList.remove("active");
    resetPreviewPlayerUI();

    const cleanBtn    = document.getElementById("ttw-btn-voice-clean");
    const statusBadge = document.getElementById("ttw-voice-enhance-status");
    const processingEl= document.getElementById("ttw-voice-processing-indicator");
    if (cleanBtn)     { cleanBtn.classList.remove("active"); }
    if (statusBadge)  { statusBadge.classList.remove("active"); }
    if (processingEl) { processingEl.classList.remove("active"); }
};

/** Resets the preview player's progress bar, time display, and play icon. */
const resetPreviewPlayerUI = () => {
    const bar    = document.getElementById("ttw-preview-progress-bar");
    const timeEl = document.getElementById("ttw-preview-time");
    const icon   = document.querySelector("#ttw-preview-play-btn i");
    if (bar)    bar.style.width = "0%";
    if (timeEl) timeEl.textContent = "0:00";
    if (icon)   icon.className = "fa-solid fa-play";
};

/**
 * Attaches timeupdate/ended listeners to the preview <audio> element.
 * Uses a flag to prevent duplicate bindings across retake cycles.
 */
const attachPreviewAudioListeners = () => {
    if (!previewAudioEl) return;

    // Remove old listeners by cloning then re-assigning (clean approach)
    previewAudioEl.ontimeupdate = () => {
        if (!previewAudioEl.duration) return;
        const pct    = (previewAudioEl.currentTime / previewAudioEl.duration) * 100;
        const bar    = document.getElementById("ttw-preview-progress-bar");
        const timeEl = document.getElementById("ttw-preview-time");
        if (bar)    bar.style.width = pct + "%";
        if (timeEl) timeEl.textContent = formatAudioTime(previewAudioEl.currentTime);
    };

    previewAudioEl.onended = () => {
        const icon = document.querySelector("#ttw-preview-play-btn i");
        const bar  = document.getElementById("ttw-preview-progress-bar");
        if (icon) icon.className = "fa-solid fa-play";
        if (bar)  bar.style.width = "0%";
    };
};

/** Toggles play/pause on the preview audio element. */
const togglePreviewPlayback = () => {
    if (!previewAudioEl) return;
    const icon = document.querySelector("#ttw-preview-play-btn i");

    if (previewAudioEl.paused) {
        previewAudioEl.play().catch(err => console.warn("[TTW] Preview play blocked:", err));
        if (icon) icon.className = "fa-solid fa-pause";
    } else {
        previewAudioEl.pause();
        if (icon) icon.className = "fa-solid fa-play";
    }
};

/**
 * Handles the "Retake" button.
 * Discards the current recording and resets everything so the user
 * can immediately tap "Voice" to record again.
 */
const handleVoiceRetake = () => {
    // Stop playback first
    if (previewAudioEl && !previewAudioEl.paused) {
        previewAudioEl.pause();
    }

    // Fully clear all audio state
    clearPendingAudio();

    showToast("Recording discarded. Tap Voice to record again.", "info");
};

/**
 * Handles the "Clean Voice" toggle button.
 *
 * ON  → processes rawAudioBlob through the Web Audio API pipeline
 *        (highpass filter + dynamics compressor) and stages the result
 *        as pendingAudioBlob. Also updates the preview player.
 * OFF → reverts pendingAudioBlob back to rawAudioBlob and updates preview.
 */
const handleVoiceCleanToggle = async () => {
    if (!rawAudioBlob) return;

    const cleanBtn     = document.getElementById("ttw-btn-voice-clean");
    const statusBadge  = document.getElementById("ttw-voice-enhance-status");
    const processingEl = document.getElementById("ttw-voice-processing-indicator");

    voiceCleanEnabled = !voiceCleanEnabled;

    if (voiceCleanEnabled) {
        // ── Turning ON: process the audio ────────────────────────────────────
        if (cleanBtn)    { cleanBtn.disabled = true; }
        if (processingEl){ processingEl.classList.add("active"); }

        try {
            const processedBlob = await applyVoiceEnhancement(rawAudioBlob);
            pendingAudioBlob    = processedBlob;

            // Update the preview player to play the processed version
            if (previewAudioEl) {
                const wasPlaying = !previewAudioEl.paused;
                previewAudioEl.pause();
                URL.revokeObjectURL(previewAudioEl.src);
                previewAudioEl.src = URL.createObjectURL(processedBlob);
                previewAudioEl.load();
                attachPreviewAudioListeners();
                resetPreviewPlayerUI();
                if (wasPlaying) {
                    previewAudioEl.play().catch(() => {});
                }
            }

            if (cleanBtn)    { cleanBtn.classList.add("active"); }
            if (statusBadge) { statusBadge.classList.add("active"); }
            showToast("Voice cleaned & enhanced! ✨", "success");

        } catch (err) {
            console.error("[TTW] Voice enhancement failed:", err);
            voiceCleanEnabled = false;
            showToast("Enhancement failed. Using original audio.", "error");
        } finally {
            if (cleanBtn)    { cleanBtn.disabled = false; }
            if (processingEl){ processingEl.classList.remove("active"); }
        }

    } else {
        // ── Turning OFF: revert to raw blob ──────────────────────────────────
        pendingAudioBlob = rawAudioBlob;

        if (previewAudioEl) {
            previewAudioEl.pause();
            URL.revokeObjectURL(previewAudioEl.src);
            previewAudioEl.src = URL.createObjectURL(rawAudioBlob);
            previewAudioEl.load();
            attachPreviewAudioListeners();
            resetPreviewPlayerUI();
        }

        if (cleanBtn)    { cleanBtn.classList.remove("active"); }
        if (statusBadge) { statusBadge.classList.remove("active"); }
        showToast("Reverted to original recording.", "info");
    }
};

/**
 * FEATURE 2 UPGRADE — Web Audio API processing pipeline.
 *
 * Pipeline applied to the raw audio blob:
 *   1. BiquadFilterNode  (highpass @ configurable Hz) — cuts wind/rumble
 *   2. DynamicsCompressorNode (configurable params)   — normalises volume
 *
 * The processed audio is rendered offline at the same sample rate as the
 * decoded source, then re-encoded to audio/webm via MediaRecorder.
 *
 * @param {Blob} inputBlob - Raw audio blob from MediaRecorder.
 * @returns {Promise<Blob>} - Processed audio blob (audio/webm).
 */
const applyVoiceEnhancement = async (inputBlob) => {
    // Read enhancement config from site-config.js with sensible defaults
    const enhCfg = (CFG.voiceNotes && CFG.voiceNotes.voiceEnhance) || {};
    const hpFreq  = enhCfg.highpassFrequency  ?? 80;
    const hpQ     = enhCfg.highpassQ          ?? 0.707;
    const cThresh = enhCfg.compressorThreshold ?? -24;
    const cKnee   = enhCfg.compressorKnee     ?? 30;
    const cRatio  = enhCfg.compressorRatio    ?? 4;
    const cAttack = enhCfg.compressorAttack   ?? 0.003;
    const cRelease= enhCfg.compressorRelease  ?? 0.25;

    // Step 1 — Decode the raw blob to an AudioBuffer
    const arrayBuffer  = await inputBlob.arrayBuffer();
    const tempCtx      = new AudioContext();
    const sourceBuffer = await tempCtx.decodeAudioData(arrayBuffer);
    await tempCtx.close();

    // Step 2 — Set up an OfflineAudioContext matching the source's specs
    const offlineCtx = new OfflineAudioContext(
        sourceBuffer.numberOfChannels,
        sourceBuffer.length,
        sourceBuffer.sampleRate
    );

    // Step 3 — Build the processing graph:
    //   BufferSource → HighpassFilter → DynamicsCompressor → Destination
    const sourceNode = offlineCtx.createBufferSource();
    sourceNode.buffer = sourceBuffer;

    const highpass = offlineCtx.createBiquadFilter();
    highpass.type            = "highpass";
    highpass.frequency.value = hpFreq;
    highpass.Q.value         = hpQ;

    const compressor = offlineCtx.createDynamicsCompressor();
    compressor.threshold.value = cThresh;
    compressor.knee.value      = cKnee;
    compressor.ratio.value     = cRatio;
    compressor.attack.value    = cAttack;
    compressor.release.value   = cRelease;

    sourceNode.connect(highpass);
    highpass.connect(compressor);
    compressor.connect(offlineCtx.destination);

    // Step 4 — Render synchronously in the offline context
    sourceNode.start(0);
    const renderedBuffer = await offlineCtx.startRendering();

    // Step 5 — Re-encode the rendered AudioBuffer back to a Blob via MediaRecorder.
    //
    // We pipe the rendered buffer through a live AudioContext → MediaStreamDestination
    // → MediaRecorder to produce a valid audio/webm blob that any browser can play.
    return new Promise((resolve, reject) => {
        const liveCtx         = new AudioContext();
        const streamDest      = liveCtx.createMediaStreamDestination();
        const playbackSource  = liveCtx.createBufferSource();
        playbackSource.buffer = renderedBuffer;
        playbackSource.connect(streamDest);

        const mimeType = MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
            ? "audio/webm;codecs=opus"
            : "audio/webm";

        const recorder = new MediaRecorder(streamDest.stream, { mimeType });
        const chunks   = [];

        recorder.ondataavailable = (e) => {
            if (e.data && e.data.size > 0) chunks.push(e.data);
        };

        recorder.onstop = async () => {
            await liveCtx.close();
            resolve(new Blob(chunks, { type: mimeType }));
        };

        recorder.onerror = async (e) => {
            await liveCtx.close();
            reject(e.error || new Error("MediaRecorder error during re-encoding"));
        };

        recorder.start(100);
        playbackSource.start(0);

        // Stop the recorder as soon as the buffer has finished playing
        playbackSource.onended = () => {
            if (recorder.state === "recording") recorder.stop();
        };
    });
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 11 — FEATURE 4: TELEGRAM NOTIFICATIONS
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Sends an async Telegram bot notification when a new comment is posted.
 * This is a fire-and-forget function — failures are logged silently.
 * @param {string} message  - The comment text.
 * @param {string} userName - The commenter's display name.
 */
const sendTelegramNotification = async (message, userName) => {
    if (!CFG.telegram || !CFG.telegram.enabled) return;

    const endpoint = CFG.telegram.endpoint || "/api/telegram-notify";
    const baseUrl  = (window.SITE_CONFIG && window.SITE_CONFIG.baseUrl) || window.location.origin;

    try {
        const response = await fetch(endpoint, {
            method : "POST",
            headers: { "Content-Type": "application/json" },
            body   : JSON.stringify({
                pageId   : String(currentPageId || "home").slice(0, 120),
                message  : String(message || "").slice(0, 2000),
                userName : String(userName || "Anonymous").slice(0, 120),
                baseUrl  : baseUrl
            })
        });

        if (!response.ok) {
            throw new Error(`Telegram endpoint returned HTTP ${response.status}`);
        }
    } catch (err) {
        // Telegram failure must never block the comment post.
        console.warn("[TTW] Telegram notification failed (non-critical):", err);
    }
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 12 — FEATURE 8: ANTI-SPAM COOLDOWN DISPLAY TIMER
// ══════════════════════════════════════════════════════════════════════════════

let cooldownDisplayInterval = null;

/**
 * Shows a live countdown in the toolbar while the anti-spam cooldown is active.
 * Automatically hides itself when the timer expires.
 */
const startCooldownDisplayTimer = () => {
    if (cooldownDisplayInterval) clearInterval(cooldownDisplayInterval);

    const msgEl = document.getElementById("ttw-cooldown-msg");
    const valEl = document.getElementById("ttw-cooldown-val");
    if (!msgEl || !valEl) return;

    const tick = () => {
        const remaining = getCooldownRemaining();
        if (remaining <= 0) {
            msgEl.classList.remove("active");
            clearInterval(cooldownDisplayInterval);
            cooldownDisplayInterval = null;
        } else {
            msgEl.classList.add("active");
            valEl.textContent = remaining;
        }
    };
    tick();
    cooldownDisplayInterval = setInterval(tick, 1000);
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 13 — FEATURE 14: GDPR — EXPORT MY DATA
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Exports all of the current user's comments for this page as a .txt file.
 * Triggers a browser download using a dynamically created anchor element.
 */
const handleExportData = async () => {
    if (!currentUser) return;

    showToast("Preparing your data export…", "info");

    try {
        const q        = query(commentsRef, where("pageId", "==", currentPageId), where("uid", "==", currentUser.uid));
        const snapshot = await getDocs(q);
        const myComments = snapshot.docs.map(d => d.data());

        if (!myComments.length) {
            showToast("No comments found to export.", "info");
            return;
        }

        let content  = `=== Comment Data Export ===\n`;
        content += `User    : ${currentUser.displayName} (${currentUser.email})\n`;
        content += `Page    : ${currentPageId}\n`;
        content += `Exported: ${new Date().toLocaleString()}\n`;
        content += `${"=".repeat(40)}\n\n`;

        myComments.forEach((c, i) => {
            content += `[${i + 1}] ${c.timestamp ? new Date(c.timestamp.seconds * 1000).toLocaleString() : "Unknown time"}\n`;
            content += `${c.message}\n`;
            if (c.imageURL) content += `[Attached Image: ${c.imageURL}]\n`;
            if (c.audioURL) content += `[Attached Audio: ${c.audioURL}]\n`;
            content += "\n";
        });

        const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
        const url  = URL.createObjectURL(blob);
        const a    = document.createElement("a");
        a.href     = url;
        a.download = `my-comments-${currentPageId}-${Date.now()}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        showToast("Data exported successfully! ✓", "success");
    } catch (err) {
        console.error("[TTW] Export Error:", err);
        showToast("Export failed. Please try again.", "error");
    }
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 14 — FEATURE 15: SEO SCHEMA (JSON-LD)
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Generates and injects a DiscussionForumPosting JSON-LD schema into <head>.
 * Fired after comments are rendered. Removes any previous schema to stay current.
 * @param {Object[]} comments - The array of rendered top-level comment objects.
 */
const injectSEOSchema = (comments) => {
    if (!CFG.seoSchema || !CFG.seoSchema.enabled) return;

    // Remove any previously injected schema to avoid duplicates
    const old = document.getElementById("ttw-schema-jsonld");
    if (old) old.remove();

    if (!comments.length) return;

    const baseUrl   = (window.SITE_CONFIG && window.SITE_CONFIG.baseUrl) || window.location.origin;
    const brandName = (window.SITE_CONFIG && window.SITE_CONFIG.brandName) || "Website";
    const pageUrl   = window.location.href;

    const schema = {
        "@context"        : "https://schema.org",
        "@type"           : "DiscussionForumPosting",
        "url"             : pageUrl,
        "name"            : `Community Discussion — ${currentPageId}`,
        "author"          : { "@type": "Organization", "name": brandName, "url": baseUrl },
        "commentCount"    : comments.length,
        "comment"         : comments.slice(0, 20).map(c => ({  // Cap at 20 for schema size
            "@type"       : "Comment",
            "text"        : (c.message || "").substring(0, 500),
            "author"      : { "@type": "Person", "name": c.name || "Anonymous" },
            "dateCreated" : c.timestamp ? new Date(c.timestamp.seconds * 1000).toISOString() : new Date().toISOString()
        }))
    };

    const script    = document.createElement("script");
    script.id       = "ttw-schema-jsonld";
    script.type     = "application/ld+json";
    script.textContent = JSON.stringify(schema);
    document.head.appendChild(script);
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 15 — RENDERING ENGINE
// Converts commentsData array into DOM HTML, applying all visual features.
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Main render function. Applies sorting, pagination, ads, pinned logic,
 * and rebuilds the entire comments list DOM.
 */
const renderCommentsUI = () => {
    const listContainer = document.getElementById("ttw-comments-list");
    if (!listContainer) return;

    const isUserAdmin = !!(currentUser && ADMIN_EMAILS.includes(currentUser.email));

    // Separate main (top-level) comments and replies
    const mainComments = commentsData.filter(c => !c.parentId);
    const replies      = commentsData.filter(c =>  c.parentId);

    // Apply sorting
    const sorted = sortComments(mainComments);

    // Update count label
    const countLabel = document.getElementById("ttw-count-label");
    if (countLabel) countLabel.textContent = `${mainComments.length} Comment${mainComments.length !== 1 ? "s" : ""}`;

    // Sync sort dropdown visual state
    const sortSelect = document.getElementById("ttw-sort-select");
    if (sortSelect) sortSelect.value = currentSort;

    if (!sorted.length) {
        listContainer.innerHTML = `
            <div class="ttw-empty-state">
                <i class="fa-regular fa-comment-dots"></i>
                <p>Be the first to leave a comment!</p>
            </div>
        `;
        injectSEOSchema([]);
        return;
    }

    let htmlOutput    = "";
    let renderedCount = 0;
    const adInterval  = (CFG.ads && CFG.ads.enabled && CFG.ads.injectAfterN) || 0;

    // Pinned comments always appear first
    const pinned   = sorted.filter(c =>  c.isPinned);
    const unpinned = sorted.filter(c => !c.isPinned);
    const ordered  = [...pinned, ...unpinned];

    ordered.forEach((main) => {
        htmlOutput += buildCommentHTML(main, isUserAdmin, false);
        renderedCount++;

        // Find and append replies for this comment
        const commentReplies = replies
            .filter(r => r.parentId === main.id)
            .sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0)); // Oldest first
        commentReplies.forEach(reply => {
            htmlOutput += buildCommentHTML(reply, isUserAdmin, true);
        });

        // FEATURE 10 — Inject ad unit after every N comments
        if (adInterval > 0 && renderedCount % adInterval === 0 && !main.isPinned) {
            htmlOutput += `<div class="ttw-ad-unit">${CFG.ads.adHTML || ""}</div>`;
        }
    });

    listContainer.innerHTML = htmlOutput;

    // Attach audio player event listeners to the newly rendered DOM
    attachAudioPlayerListeners();

    // FEATURE 15 — Update JSON-LD schema with current comments
    injectSEOSchema(sorted);
};

/**
 * Sorts an array of comment objects based on the current sort mode.
 * @param {Object[]} comments - Array of comment data objects.
 * @returns {Object[]} - Sorted copy of the array.
 */
const sortComments = (comments) => {
    const copy = [...comments];
    if (currentSort === "mostLiked") {
        return copy.sort((a, b) => (b.upvotes || 0) - (a.upvotes || 0));
    }
    // Default: newest first (by Firestore timestamp)
    return copy.sort((a, b) => {
        const ta = a.timestamp ? a.timestamp.seconds : 0;
        const tb = b.timestamp ? b.timestamp.seconds : 0;
        return tb - ta;
    });
};

/**
 * Builds the complete HTML for a single comment or reply card.
 * This is the core template function — handles all 15 feature integrations.
 *
 * @param {Object}  data        - The Firestore comment document data + id.
 * @param {boolean} isUserAdmin - Whether the current viewer is an admin.
 * @param {boolean} isReply     - If true, applies reply-specific CSS classes.
 * @returns {string} - HTML string for one comment card.
 */
const buildCommentHTML = (data, isUserAdmin, isReply) => {
    const boxClass = isReply ? "ttw-comment-box ttw-reply-box" : `ttw-comment-box${data.isPinned ? " pinned" : ""}`;
    const isOwner  = !!(currentUser && currentUser.uid === data.uid);

    // ── FEATURE 12: BADGES ──────────────────────────────────────────────────
    let badgesHTML = "";
    if (data.isAdmin) {
        badgesHTML += `<span class="ttw-admin-badge"><i class="fa-solid fa-shield-halved"></i> ADMIN</span>`;
    }
    if (!data.isAdmin && CFG.badges && CFG.badges.enabled) {
        const threshold = CFG.badges.trustedUserUpvoteThreshold || 10;
        if ((data.upvotes || 0) >= threshold) {
            badgesHTML += `<span class="ttw-trusted-badge"><i class="fa-solid fa-star"></i> TRUSTED</span>`;
        }
    }

    // ── FEATURE 6: PINNED BADGE ─────────────────────────────────────────────
    const pinnedBadge = (data.isPinned && !isReply)
        ? `<span class="ttw-pinned-badge"><i class="fa-solid fa-thumbtack"></i> Pinned</span>`
        : "";

    // ── FEATURE 3, 5, 6: ACTION BUTTONS ────────────────────────────────────
    let actionsHTML = "";

    // Upvote button (Feature 5)
    if (!isReply && CFG.upvotes && CFG.upvotes.enabled && currentUser) {
        const hasVoted   = (data.upvotedBy || []).includes(currentUser.uid);
        const votedClass = hasVoted ? "voted" : "";
        actionsHTML += `
            <button class="ttw-action-btn ttw-btn-upvote ${votedClass}" data-id="${data.id}">
                <i class="fa-${hasVoted ? "solid" : "regular"} fa-thumbs-up"></i>
                <span class="ttw-upvote-count">${data.upvotes || 0}</span>
            </button>`;
    } else if (!isReply && CFG.upvotes && CFG.upvotes.enabled) {
        // Show count even when not logged in
        actionsHTML += `
            <span style="font-size:0.82rem;color:var(--text-muted,#8b949e);display:flex;align-items:center;gap:4px;">
                <i class="fa-regular fa-thumbs-up"></i> ${data.upvotes || 0}
            </span>`;
    }

    // Reply button
    if (!isReply && currentUser) {
        actionsHTML += `<button class="ttw-action-btn ttw-btn-reply" data-id="${data.id}"><i class="fa-solid fa-reply"></i> Reply</button>`;
    }

    // Edit button (Feature 3) — only for comment owner
    if (isOwner && CFG.userCRUD && CFG.userCRUD.editEnabled) {
        actionsHTML += `<button class="ttw-action-btn ttw-btn-edit" data-id="${data.id}"><i class="fa-regular fa-pen-to-square"></i> Edit</button>`;
    }

    // Delete button — owner or admin
    const canDelete = (isOwner && CFG.userCRUD && CFG.userCRUD.deleteEnabled) || isUserAdmin;
    if (canDelete) {
        actionsHTML += `<button class="ttw-action-btn ttw-btn-delete" data-id="${data.id}"><i class="fa-solid fa-trash-can"></i> Delete</button>`;
    }

    // Pin/Unpin button (Feature 6) — admin only, top-level only
    if (!isReply && isUserAdmin && CFG.pinComment && CFG.pinComment.enabled) {
        const pinClass = data.isPinned ? "ttw-btn-pin active-pin" : "ttw-btn-pin";
        actionsHTML += `
            <button class="ttw-action-btn ${pinClass}" data-id="${data.id}" data-pinned="${!!data.isPinned}">
                <i class="fa-solid fa-thumbtack"></i> ${data.isPinned ? "Unpin" : "Pin"}
            </button>`;
    }

    // ── FEATURE 1: IMAGE ATTACHMENT IN COMMENT ──────────────────────────────
    const imageHTML = data.imageURL
        ? `<img src="${escapeHTML(data.imageURL)}" alt="Attachment" class="ttw-comment-image" loading="lazy">`
        : "";

    // ── FEATURE 2: CUSTOM AUDIO PLAYER ─────────────────────────────────────
    const audioHTML = data.audioURL
        ? buildAudioPlayerHTML(data.audioURL, data.id)
        : "";

    // ── FEATURE 9, 11, 13: PROCESS COMMENT TEXT ────────────────────────────
    const processedText = processCommentText(data.message || "");

    // ── FEATURE 3: EDITED LABEL ─────────────────────────────────────────────
    const editedLabel = data.isEdited
        ? `<span class="ttw-edited-label">(edited)</span>`
        : "";

    // ── FEATURE 3: INLINE EDIT FORM ─────────────────────────────────────────
    const editFormHTML = (isOwner && CFG.userCRUD && CFG.userCRUD.editEnabled) ? `
        <div class="ttw-edit-container" id="edit-container-${data.id}">
            <textarea class="ttw-textarea" id="edit-textarea-${data.id}"
                style="min-height:70px;font-size:0.9rem;">${escapeHTML(data.message || "")}</textarea>
            <div class="ttw-edit-actions">
                <button class="ttw-btn-save-edit" data-id="${data.id}">Save</button>
                <button class="ttw-btn-cancel-edit" data-id="${data.id}">Cancel</button>
            </div>
        </div>` : "";

    // ── REPLY INPUT BOX ─────────────────────────────────────────────────────
    const replyInputHTML = (!isReply && currentUser) ? `
        <div id="reply-container-${data.id}" class="ttw-reply-input-container">
            <textarea id="reply-input-${data.id}" class="ttw-textarea"
                placeholder="Write a reply to ${escapeHTML(data.name || "this user")}…"
                style="min-height:55px;padding:10px;font-size:0.9rem;"></textarea>
            <div class="ttw-clearfix">
                <button id="submit-reply-${data.id}" class="ttw-submit-btn ttw-submit-reply-btn"
                    data-parent-id="${data.id}"
                    style="padding:6px 18px;font-size:0.85rem;margin-top:8px;">
                    Reply <i class="fa-solid fa-paper-plane"></i>
                </button>
            </div>
        </div>` : "";

    // ── AVATAR (with XSS-safe fallback) ────────────────────────────────────
    const avatarSrc = escapeHTML(data.photoURL || "");
    const avatarFallback = `this.src='data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 40 40%22%3E%3Ccircle cx=%2220%22 cy=%2215%22 r=%228%22 fill=%22%2300e5ff%22/%3E%3Cellipse cx=%2220%22 cy=%2232%22 rx=%2213%22 ry=%228%22 fill=%22%2300e5ff%22/%3E%3C/svg%3E'`;

    return `
        <div class="${boxClass}" id="comment-${data.id}">
            <div class="ttw-comment-header">
                <div class="ttw-comment-meta">
                    <img src="${avatarSrc}" alt="Avatar" class="ttw-comment-avatar" onerror="${avatarFallback}">
                    <div>
                        <div class="ttw-comment-author">
                            ${escapeHTML(data.name || "Anonymous")}
                            ${badgesHTML}
                            ${pinnedBadge}
                        </div>
                        <div class="ttw-comment-time">${timeAgo(data.timestamp)} ${editedLabel}</div>
                    </div>
                </div>
            </div>

            <div class="ttw-comment-body" id="comment-body-${data.id}">
                ${processedText}
                ${imageHTML}
                ${audioHTML}
            </div>

            ${editFormHTML}

            ${actionsHTML ? `<div class="ttw-comment-actions">${actionsHTML}</div>` : ""}
            ${replyInputHTML}
        </div>
    `;
};

/**
 * Builds the custom HTML5 audio player UI for a comment's voice note.
 * Uses a hidden <audio> element driven by JS for full UI control.
 * @param {string} url       - The Cloudinary audio URL.
 * @param {string} commentId - The comment's Firestore ID (used for unique IDs).
 * @returns {string} - HTML string for the audio player widget.
 */
const buildAudioPlayerHTML = (url, commentId) => `
    <div class="ttw-audio-player" data-comment-id="${commentId}">
        <audio src="${escapeHTML(url)}" preload="none" id="audio-${commentId}" style="display:none;"></audio>
        <button class="ttw-audio-play-btn" title="Play / Pause">
            <i class="fa-solid fa-play"></i>
        </button>
        <div class="ttw-audio-progress-wrap">
            <div class="ttw-audio-progress-bg">
                <div class="ttw-audio-progress-bar" id="audio-bar-${commentId}"></div>
            </div>
        </div>
        <span class="ttw-audio-time" id="audio-time-${commentId}">0:00</span>
    </div>
`;

/**
 * Attaches event listeners to all custom audio players in the rendered list.
 * Must be called after innerHTML is updated in renderCommentsUI().
 */
const attachAudioPlayerListeners = () => {
    document.querySelectorAll(".ttw-audio-player").forEach(player => {
        const commentId = player.getAttribute("data-comment-id");
        const audio     = document.getElementById("audio-" + commentId);
        const bar       = document.getElementById("audio-bar-" + commentId);
        const timeEl    = document.getElementById("audio-time-" + commentId);

        if (!audio) return;

        // Update progress bar and time display as audio plays
        audio.addEventListener("timeupdate", () => {
            if (audio.duration) {
                const pct = (audio.currentTime / audio.duration) * 100;
                if (bar)    bar.style.width = pct + "%";
                if (timeEl) timeEl.textContent = formatAudioTime(audio.currentTime);
            }
        });

        // Reset play button icon when audio ends
        audio.addEventListener("ended", () => {
            const btn = player.querySelector(".ttw-audio-play-btn i");
            if (btn) btn.className = "fa-solid fa-play";
            if (bar) bar.style.width = "0%";
        });
    });
};

/**
 * Toggles play/pause on a custom audio player widget.
 * Also stops any other playing audio to allow only one at a time.
 * @param {HTMLElement} player - The .ttw-audio-player container element.
 */
const toggleAudioPlayer = (player) => {
    const commentId = player.getAttribute("data-comment-id");
    const audio     = document.getElementById("audio-" + commentId);
    const icon      = player.querySelector(".ttw-audio-play-btn i");

    if (!audio) return;

    // Pause all other audio players first
    document.querySelectorAll(".ttw-audio-player").forEach(p => {
        if (p !== player) {
            const otherId    = p.getAttribute("data-comment-id");
            const otherAudio = document.getElementById("audio-" + otherId);
            const otherIcon  = p.querySelector(".ttw-audio-play-btn i");
            if (otherAudio && !otherAudio.paused) {
                otherAudio.pause();
                if (otherIcon) otherIcon.className = "fa-solid fa-play";
            }
        }
    });

    if (audio.paused) {
        audio.play().catch(err => console.warn("[TTW] Audio play blocked:", err));
        if (icon) icon.className = "fa-solid fa-pause";
    } else {
        audio.pause();
        if (icon) icon.className = "fa-solid fa-play";
    }
};

/**
 * Formats a duration in seconds to "M:SS" display format.
 * @param {number} seconds - Time in seconds.
 * @returns {string} - e.g. "1:42"
 */
const formatAudioTime = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s.toString().padStart(2, "0")}`;
};

/**
 * FEATURE 3 — Toggles the inline edit textarea for a specific comment.
 * Shows or hides the edit form by toggling the 'active' class.
 * @param {string}  commentId - The Firestore document ID.
 * @param {boolean} show      - true to open the edit form, false to close.
 */
const toggleEditMode = (commentId, show) => {
    const editContainer = document.getElementById("edit-container-" + commentId);
    const commentBody   = document.getElementById("comment-body-" + commentId);
    if (editContainer) editContainer.classList.toggle("active", show);
    if (commentBody)   commentBody.style.display = show ? "none" : "";
};


// ══════════════════════════════════════════════════════════════════════════════
// SECTION 16 — WIDGET BOOT
// Safe initialization with error boundaries.
// ══════════════════════════════════════════════════════════════════════════════

try {
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initWidget);
    } else {
        initWidget();
    }
} catch (err) {
    console.error("[TTW Comments] Critical widget load error:", err);
    const container = document.querySelector(".trusted-comments-widget");
    if (container) {
        container.innerHTML = `
            <div style="padding:20px;text-align:center;color:#ff4757;border:1px solid rgba(255,71,87,0.3);border-radius:10px;">
                <i class="fa-solid fa-triangle-exclamation"></i>
                Comment system failed to load. Please refresh or check the console for errors.
            </div>
        `;
    }
}
